  display:flex;
  flex-wrap:wrap;
  gap:9px;
  margin:20px 0;
}
.mc-badge{
  background:#d4af37;
  color:#111!important;
  font-size:13px;
  font-weight:800;
  padding:8px 14px;
  border-radius:999px;
}
.mc-features{
  list-style:none!important;
  padding:0!important;
  margin:14px 0!important;
}
.mc-features li{
  position:relative;
  padding:8px 0 8px 27px;
  color:#ededed!important;
  border-bottom:1px solid rgba(255,255,255,.07);
}
.mc-features li:before{
  content:"✓";
  position:absolute;
  left:0;
  color:#d4af37;
  font-weight:900;
}
.mc-details{
  background:rgba(255,255,255,.04);
  border:1px solid rgba(255,255,255,.10);
  border-radius:12px;
  padding:8px 18px;
}
.mc-detail-row{
  display:flex;
  gap:15px;
  padding:11px 0;
  border-bottom:1px solid rgba(255,255,255,.08);
  font-size:14px;
}
.mc-detail-row:last-child{border-bottom:none;}
.mc-detail-label{
  min-width:155px;
  color:#d4af37;
  font-weight:800;
}
.mc-detail-value{color:#f1f1f1;}
.mc-note{
  margin-top:20px;
  background:rgba(255,255,255,.04);
  border-radius:10px;
  padding:14px 16px;
  color:#d5d5d5;
  font-size:13px;
  line-height:1.6;
}
.mc-trust{
  margin-top:22px;
  padding-top:16px;
  border-top:1px solid rgba(255,255,255,.12);
  color:#d5d5d5;
  font-size:13px;
  line-height:1.6;
}
@media(max-width:768px){
  .mc-product-premium{padding:24px 20px;}
  .mc-product-premium h2{font-size:23px;}
  .mc-detail-row{display:block;}
  .mc-detail-label{display:block;margin-bottom:3px;}
}





